import json
try:
    vars['fin'] = 'yes'
    for i in (1, 2, 3):
        vars['note' + str(i) + '_pid'] = ''
        vars['note' + str(i) + '_reason'] = ''
    P = json.loads(vars.get('pj') or '[]')
    sc = int(float(vars.get('create_promise_success_count') or 0))
    ns = len([p for p in P if vars.get('sent_' + p['pid']) == '1'])
    for p in P:
        if vars.get('sent_' + p['pid']) == '1':
            p['prom'] = 1 if (vars.get('last_' + p['pid']) == 'ok' or (sc >= ns and vars.get('last_' + p['pid']) != 'fail')) else 0
            if not p['prom'] and vars.get('fin') == 'yes':
                p['res'] = 'service_error'
        p['fails'] = max(int(p.get('fails') or 0), int(vars.get('fail_' + p['pid']) or 0))
        if p['fails'] >= 2 and not p['prom']:
            p['res'] = 'service_error'
    if vars.get('transfer_reason'):
        vars['outcome'] = 'transferred'
        vars['reason'] = vars.get('transfer_reason')
    elif vars.get('verified') == 'yes' and P:
        rs = []
        k = 0
        for p in P:
            if not p['prom']:
                r = p['res'] or 'refused'
                rs.append(r)
                if len(P) > 1:
                    k += 1
                    vars['note' + str(k) + '_pid'] = p['pid']
                    vars['note' + str(k) + '_reason'] = r
        if any(p['prom'] for p in P):
            vars['outcome'] = 'promise'
            vars['reason'] = ''
        elif all(r == 'paid' for r in rs):
            vars['outcome'] = 'paid'
            vars['reason'] = ''
        else:
            vars['outcome'] = 'no_promise'
            vars['reason'] = [r for r in rs if r != 'paid'][0]
except Exception:
    pass

