    P = json.loads(vars.get('pj') or '[]')
    sc = int(float(vars.get('create_promise_success_count') or 0))
    ns = len([p for p in P if vars.get('sent_' + p['pid']) == '1'])
    for p in P:
        if vars.get('sent_' + p['pid']) == '1':
            p['prom'] = 1 if (vars.get('last_' + p['pid']) == 'ok' or (sc >= ns and vars.get('last_' + p['pid']) != 'fail')) else 0
            if not p['prom'] and vars.get('fin') == 'yes':
                p['res'] = 'service_error'
        p['fails'] = max(int(p.get('fails') or 0), int(vars.get('fail_' + p['pid']) or 0))
        if p['fails'] >= 2 and not p['prom']:
            p['res'] = 'service_error'
    def close(o, r, bye):
        vars['outcome'] = o
        vars['reason'] = r
        vars['bye_line'] = bye
        vars['done'] = 'yes'
    TY = 'Thank you for your time. Goodbye.'
    if not ver:
        if what == 'wrong_number':
            close('not_reached', 'wrong_number', 'Sorry to have bothered you. Thank you, goodbye.')
        elif what == 'deceased':
            close('not_reached', 'deceased', 'I am sorry for your loss. Goodbye.')
        elif what == 'unclear':
            n = int(vars.get('asks') or 0) + 1
            vars['asks'] = n
            if n >= 2:
                close('not_reached', 'unclear', TY)
            else:
                vars['next_line'] = 'Answer any question the person asked, then ask once more whether you are speaking with the customer. This is the second and last ask.'
        elif what == 'no_callback':
            close('not_reached', 'no_callback', TY)
        elif what in ('declined', 'refused'):
            n = int(vars.get('decl') or 0) + 1
            vars['decl'] = n
            if n >= 2:
                close('not_verified', 'declined', TY)
            else:
                vars['next_line'] = 'Explain once that the questions protect their account, and ask the question again.'
    else:
        tg = [p for p in P if (pid == 'all' or p['pid'] == pid) and not p['prom'] and not p['res']]
        if what == 'product_closed_before':
            what = 'dispute'
        if vars.get('hard') == 'yes' and what in ('attempt', 'refused'):
            what = 'hardship'
            pid = 'all'
            tg = [p for p in P if not p['prom'] and not p['res']]
        if what == 'hardship_mentioned':
            vars['hard'] = 'yes'
            vars['next_line'] = 'Hardship: say one short sentence of sympathy, make NO persuasion attempt, offer the customer support team. Accepts: transfer_to_agent queue support. Declines: mark what=hardship. A date or amount the customer names is still recorded.'
        elif what == 'attempt':
            for p in tg[:1]:
                p['att'] += 1
                vars['next_line'] = p['name'] + ': attempts used ' + str(p['att']) + ' of ' + str(p['allowed']) + ('. If the customer says no again, call mark with what=refused for this product.' if p['att'] >= p['allowed'] else '. One more attempt is allowed if this one is refused.')
        elif what == 'refused':
            for p in tg:
                if pid != 'all' and p['att'] < p['allowed']:
                    vars['next_line'] = p['name'] + ': not closed yet. Make persuasion attempt ' + str(p['att'] + 1) + ' first and report it with mark what=attempt.'
                else:
                    p['res'] = 'refused'
        elif what in ('hardship', 'dispute', 'paid'):
            for p in tg:
                p['res'] = what
        elif what == 'declined':
            for p in tg:
                p['res'] = 'refused'
        elif what == 'finished':
            for p in tg:
                p['res'] = 'refused'
        vars['pj'] = json.dumps(P)
        if P and all(p['prom'] or p['res'] for p in P):
            vars['done'] = 'yes'
            if what == 'paid' and not any(p['prom'] for p in P):
                vars['bye_line'] = 'Payments can take one business day to appear. Thank you for your time. Goodbye.'
        if not P and what == 'finished':
            vars['done'] = 'yes'
except Exception:
    pass

